class BlowerModel{
  public:
    static const int STATES = 40;
    static const int WINDOW = 20;
    static const int TREES  = 55;

    static const int CONFIRM   = 7;
    static const int TOLERANCE = 500;

    static constexpr float THRESHOLD = 0.412463825f;
    float prob = 0.00;

    bool get(const float* states){
        float total = 0.00;

        for(int tree=0; tree<TREES; tree++){
            uint16_t node = MODEL_ROOT[tree];

            while(MODEL_FEATURE[node] >= 0)
                node = (states[MODEL_FEATURE[node]] <= MODEL_VALUE[node]) ? (node + 1) : MODEL_RIGHT[node];

            total += MODEL_VALUE[node];
        }

        prob = total / TREES;
        return (prob > THRESHOLD);
    }
};

